def _group(n: str, loc: str, sep: str) -> str:
    if loc == "es" and len(n) == 4:
        return n
    if loc == "en-IN" and len(n) > 3:
        head, tail = n[:-3], n[-3:]
        parts = []
        while len(head) > 2:
